'use strict';

// MODULES //

var addon = require( './../src/addon.node' );


// MAIN //

/**
 * Create Continuity dictionary for Heavisidef function.
 *
 */
var CONTINUITY = {
	'half-maximum': 2,
	'left-continuous': 0,
	'right-continuous': 1
};

/**
* Evaluates the Heavisidef function.
*
* @param {number} x - input value
* @param {string} [continuity] - continuity option
* @returns {number} function value
*
* @example
* var v = heavisidef( 3.14, 'half-maximum' );
* // returns 1.0
*
* @example
* var v = heavisidef( -3.14, 'half-maximum' );
* // returns 0.0
*
* @example
* var v = heavisidef( 0.0, 'incorrect-continuity' );
* // returns NaN
*
* @example
* var v = heavisidef( 0.0, 'half-maximum' );
* // returns 0.5
*
* @example
* var v = heavisidef( 0.0, 'left-continuous' );
* // returns 0.0
*
* @example
* var v = heavisidef( 0.0, 'right-continuous' );
* // returns 1.0
*
* @example
* var v = heavisidef( NaN, 'half-maximum' );
* // returns NaN
*/
function heavisidef( x, continuity ) {
	var contInt = -1;
	if ( continuity in CONTINUITY ) {
		contInt = CONTINUITY[continuity];
	}
	return addon( x, contInt );
}


// EXPORTS //

module.exports = heavisidef;
